// Build Groq request with conversation memory
const message = $json.message || 'Hello';
const history = Array.isArray($json.conversationHistory) ? $json.conversationHistory : [];
const vendor = $json.vendor && typeof $json.vendor === 'object' ? $json.vendor : {};
const businessName = vendor.name || $json.businessName || 'Our Business';
const personalityTone = vendor.personalityTone || 'friendly';
const systemPromptOverride = vendor.systemPromptOverride;

let systemPrompt;
if (systemPromptOverride) {
  systemPrompt = systemPromptOverride;
} else {
  systemPrompt = `You are a helpful customer service AI for ${businessName}.
Personality tone: ${personalityTone}

IMPORTANT:
- REMEMBER and REFERENCE previous messages in this conversation
- If customer mentioned their name, use it
- Keep responses under 100 words
- Be helpful and personable`;
}

const messages = [{ role: 'system', content: systemPrompt }];

// Add conversation history
if (Array.isArray(history) && history.length > 0) {
  for (const msg of history) {
    if (msg.role && msg.content) {
      messages.push(msg);
    }
  }
}

// Add current message
messages.push({ role: 'user', content: message });

return {
  json: {
    model: 'llama-3.3-70b-versatile',
    messages: messages,
    temperature: 0.7,
    max_tokens: 500
  }
};

// Extract reply from Groq response
let reply = null;

if ($json.choices && Array.isArray($json.choices) && $json.choices.length > 0) {
  const firstChoice = $json.choices[0];
  if (firstChoice.message && firstChoice.message.content) {
    reply = firstChoice.message.content;
  }
}

if (!reply) {
  reply = 'Sorry, I had trouble understanding. Can you rephrase that?';
}

return { json: { reply } };
